// HasDonor applies the HasEdge predicate on the "donor" edge.
func HasDonor() predicate.PagamentoContribuicao {
	return predicate.PagamentoContribuicao(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DonorTable, DonorColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDonorWith applies the HasEdge predicate on the "donor" edge with a given conditions (other predicates).
func HasDonorWith(preds ...predicate.Doador) predicate.PagamentoContribuicao {
	return predicate.PagamentoContribuicao(func(s *sql.Selector) {
		step := newDonorStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

