// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PagamentoContribuicao) predicate.PagamentoContribuicao {
	return predicate.PagamentoContribuicao(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PagamentoContribuicao) predicate.PagamentoContribuicao {
	return predicate.PagamentoContribuicao(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PagamentoContribuicao) predicate.PagamentoContribuicao {
	return predicate.PagamentoContribuicao(sql.NotPredicates(p))
}
